    validate(exported, "name", exported.name);
    const exportAssign: t.AssignmentExpression = {
      type: "AssignmentExpression",
      operator: "=",
      left: id,
      right: exported,
    };
    validate(exportAssign, "operator", exportAssign.operator);
    validate(exportAssign, "left", exportAssign.left);
    validate(exportAssign, "right", exportAssign.right);
    const exportStmt: t.ExpressionStatement = {
      type: "ExpressionStatement",
      expression: exportAssign,
    };
    validate(exportStmt, "expression", exportStmt.expression);
    path.pushContainer("body", exportStmt);
  } else {
    throw new Error("Unexpected helper format.");
  }

  Object.keys(toRename).forEach(name => {
    path.scope.rename(name, toRename[name]);
  });

  for (const importPath of imps) importPath.remove();
  for (const refPath of impsBindingRefs) {
    const source = dependenciesRefs[refPath.node.name];
